<?php
require_once __DIR__.'/includes/functions.php';$id=(int)($_GET['id']??0);$s=$pdo->prepare("SELECT r.*,u.name uploader,s.name subject_name,s.code subject_code,d.name department_name FROM resources r JOIN users u ON u.id=r.uploaded_by LEFT JOIN subjects s ON s.id=r.subject_id LEFT JOIN departments d ON d.id=r.department_id WHERE r.id=?");$s->execute([$id]);$r=$s->fetch();if(!$r) {http_response_code(404);exit('Resource not found.');}$u=current_user();$owner=$u&&$u['id']==$r['uploaded_by'];$admin=$u&&$u['role']==='admin';if($r['status']!=='approved'&&!$owner&&!$admin){http_response_code(403);exit('This resource is awaiting approval or is unavailable.');}
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['bookmark'])){require_login();verify_csrf();$b=$pdo->prepare("SELECT id FROM bookmarks WHERE user_id=? AND resource_id=?");$b->execute([$u['id'],$id]);if($b->fetch()){$pdo->prepare("DELETE FROM bookmarks WHERE user_id=? AND resource_id=?")->execute([$u['id'],$id]);}else{$pdo->prepare("INSERT IGNORE INTO bookmarks(user_id,resource_id) VALUES(?,?)")->execute([$u['id'],$id]);}redirect('resource.php?id='.$id);}
$bookmarked=$u?is_saved($pdo,$u['id'],$id):false;$page_title=$r['title'];require __DIR__.'/includes/header.php';?>
<div class="detail-layout"><section><span class="eyebrow"><?= e(str_replace('_',' ',$r['type'])) ?></span><h1><?= e($r['title']) ?></h1><p class="muted"><?= e($r['description']) ?></p><div class="meta-list"><span>Uploaded by <b><?= e($r['uploader']) ?></b></span><span><?= e($r['department_name']??'University-wide') ?></span><?php if($r['subject_code']): ?><span><?= e($r['subject_code'].' · '.$r['subject_name']) ?></span><?php endif; ?><?php if($r['exam_year']): ?><span>Exam year <?= (int)$r['exam_year'] ?></span><?php endif; ?><span><?= number_format($r['file_size']/1024,1) ?> KB</span></div>
<div class="detail-actions"><a class="btn primary" href="<?= url('download.php?id='.$id) ?>">↓ Download document</a><?php if($u): ?><form method="post"><?= csrf_field() ?><button class="btn light" name="bookmark" value="1"><?= $bookmarked?'★ Saved':'☆ Bookmark' ?></button></form><?php endif; ?></div>
<?php if($r['mime_type']==='application/pdf'): ?><div class="pdf-frame"><iframe title="PDF preview" src="<?= url('preview.php?id='.$id) ?>"></iframe></div><?php else: ?><div class="notice">Inline preview is available for PDF files. Download this document to view it.</div><?php endif; ?></section><aside class="side-card"><h3>Resource details</h3><p><small>File name</small><br><?= e($r['original_name']) ?></p><p><small>Approval status</small><br><span class="status <?= e($r['status']) ?>"><?= e(ucfirst($r['status'])) ?></span></p><?php if($owner||$admin): ?><a href="<?= url('dashboard.php') ?>">Manage contribution →</a><?php endif; ?></aside></div>
<?php require __DIR__.'/includes/footer.php';?>